import Image from "next/image";

/* Brand lockups are generated by design/build-assets.mjs into public/brand/.
   Both day and night versions are rendered; CSS in globals.css shows the right one. */
export function Logo({ height = 40 }: { height?: number }) {
  const width = Math.round(height * 5.3);
  return (
    <>
      <Image
        className="logo-day"
        src="/brand/lockup-solid.svg"
        alt="Aston Business Intelligence"
        width={width}
        height={height}
        priority
        style={{ height, width: "auto" }}
      />
      <Image
        className="logo-night"
        src="/brand/lockup-solid-reversed.svg"
        alt="Aston Business Intelligence"
        width={width}
        height={height}
        priority
        style={{ height, width: "auto" }}
      />
    </>
  );
}

export function Mark({ size = 32, variant = "solid" }: { size?: number; variant?: "solid" | "metallic" | "badge" }) {
  return <Image src={variant === "badge" ? "/brand/badge.svg" : `/brand/mark-${variant}.svg`} alt="" width={size} height={size} />;
}
